import React, { useEffect, useState } from 'react';
import './Invitation.css';

function Invitation() {
  const [blurAmount, setBlurAmount] = useState(0);

  useEffect(() => {
    const container = document.querySelector('.container');
    const invText = document.getElementById('inv_text');

    function setContentHeight() {
      const windowHeight = window.innerHeight;
      const headerHeight = 58;
      const buttonHeight = 130;
      invText.style.minHeight = `${windowHeight - headerHeight - buttonHeight}px`;
    }

    setContentHeight();
    window.addEventListener('resize', setContentHeight);

    const handleScroll = () => {
      const scrollPosition = container.scrollTop;
      const invTextHeight = invText.offsetHeight;
      const blurStart = invTextHeight * 0.7;

      if (scrollPosition > blurStart) {
        const newBlurAmount = Math.min((scrollPosition - blurStart) / (invTextHeight * 0.3) * 5, 5);
        setBlurAmount(newBlurAmount);
      } else {
        setBlurAmount(0);
      }
    };

    container.addEventListener('scroll', handleScroll);

    return () => {
      window.removeEventListener('resize', setContentHeight);
      container.removeEventListener('scroll', handleScroll);
    };
  }, []);

  return (
    <div className="background-wrapper">
      <div className="background"></div>
      <header>
        <div className="titleArea">
          <div>
            <img
              src="/icons/back_double.png"
              alt="back"
              id="back-button"
              style={{ filter: 'brightness(0) invert(1)' }}
              onClick={() => window.history.back()}
            />
          </div>
          <div style={{ fontSize: '20px' }}>춤 이야기</div>
          <div></div>
        </div>
      </header>

      <div className="container" id="content">
        <div id="inv_text">
          <p>
            사회는 눈에 보이는, 보이지 않는<br />
            권력 관계와 규칙들로 이루어져 있다.<br /><br />
            {/* Content truncated for brevity */}
            <br /><br /><br /><br /><br /><br /><br /><br /><br /><br /><br />
          </p>
          <div
            className="blur-overlay"
            style={{
              backdropFilter: `blur(${blurAmount}px)`,
              WebkitBackdropFilter: `blur(${blurAmount}px)`,
            }}
          ></div>
        </div>
      </div>

      <div id="letsmakedance">
        <a href="/createCharacter" className="ajax-link" id="letsmakedancebutton">
          캐릭터 생성하기
        </a>
      </div>
    </div>
  );
}

export default Invitation;
